-- KO-225 group 2 missing body_id translation batch 10

update public.content_variants set body = $json${"text":"Dina wrote all her debts in a book: total, interest, minimum, and maturity. He realized that his loan had the highest interest rate. Every month he pays a minimum of two other debts and sets aside IDR 800 thousand extra for loans. In three months the loan was paid off."}$json$::jsonb, body_id = $json${"text":"Dina menulis semua utangnya di buku: total, bunga, minimum, dan jatuh tempo. Ia menyadari pinjolnya punya bunga tertinggi. Setiap bulan ia membayar minimum dua utang lainnya dan menyisihkan Rp 800 ribu ekstra untuk pinjol. Dalam tiga bulan pinjolnya lunas."}$json$::jsonb where id = 'cdacbda0-97db-4db2-ba85-0e86c75bc6f0';
update public.content_variants set body = $json${"text":"Sari has a debt of IDR 500 thousand to a friend, IDR 2 million to a loan, and IDR 3 million to a credit card. He chose the snowball method: pay off a friend's debt first to feel relieved, then move on to borrowing. The motivation from small wins helps him stay disciplined."}$json$::jsonb, body_id = $json${"text":"Sari punya utang Rp 500 ribu ke teman, Rp 2 juta ke pinjol, dan Rp 3 juta ke kartu kredit. Ia memilih metode snowball: melunasi utang teman terlebih dahulu untuk merasa lega, lalu beralih ke pinjol. Motivasi dari kemenangan kecil membantunya tetap disiplin."}$json$::jsonb where id = 'cef629d7-f476-4344-8028-87b6c2bde7ad';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Bad debt","options":["Bad debt","Good debt","Investment debt","Productive debt"],"question":"Rina borrowed IDR 1 million for a weekend holiday. What type of debt is this?","difficulty":"beginner","explanation":"Vacations do not generate income or wealth, and their value does not return once spent."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Utang buruk","options":["Utang buruk","Utang baik","Utang investasi","Utang produktif"],"question":"Rina meminjam Rp 1 juta untuk liburan akhir pekan. Jenis utang apa ini?","difficulty":"beginner","explanation":"Liburan tidak menghasilkan pendapatan atau kekayaan, dan nilainya tidak kembali setelah dibelanjakan."}$json$::jsonb where id = 'd0ecd92d-4c7b-4c62-90de-9b9a77ff527f';
update public.content_variants set body = $json${"text":"Sari saw a TikTok account promising a profit of 20% per month from crypto staking. He looked for the name of the application on the Bappebti list and couldn't find it. He decided not to deposit."}$json$::jsonb, body_id = $json${"text":"Sari melihat akun TikTok menjanjikan untung 20% per bulan dari staking kripto. Ia mencari nama aplikasi di daftar Bappebti dan tidak menemukannya. Ia memutuskan untuk tidak deposit."}$json$::jsonb where id = 'd1901dce-f7ea-46a0-a57c-24332ba3f87e';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"For planned needs that can be paid in full","options":["For planned needs that can be paid in full","To buy a new cellphone even though your savings are empty","To borrow money from friends","To withdraw as much cash as possible"],"question":"Safe use of credit cards for first-time workers is...","difficulty":"beginner","explanation":"A credit card is safe if you have the money to pay it off and use it for your needs, not impulsive desires."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Untuk kebutuhan terencana yang bisa dilunasi penuh","options":["Untuk kebutuhan terencana yang bisa dilunasi penuh","Untuk membeli ponsel baru meski tabungan kosong","Untuk meminjam uang kepada teman","Untuk menarik tunai sebanyak-banyaknya"],"question":"Penggunaan kartu kredit yang aman untuk pekerja pertama adalah...","difficulty":"beginner","explanation":"Kartu kredit aman jika kamu sudah punya uang untuk melunasinya dan menggunakannya untuk kebutuhan, bukan keinginan impulsif."}$json$::jsonb where id = 'd1aa6e3e-bd74-4a67-92c1-cf86e80e8a46';
update public.content_variants set body = $json${"text":"Diana borrowed IDR 4 million for a nurse certification course. After graduating, his salary increased from IDR 3.5 million to IDR 6 million per month. The loan is considered good debt because it increases his income. Bayu uses 12 month installments to buy a gaming headset. The headset didn't make any money and its value dropped quickly. That's bad debt."}$json$::jsonb, body_id = $json${"text":"Diana meminjam Rp 4 juta untuk kursus sertifikasi perawat. Setelah lulus, gajinya naik dari Rp 3,5 juta menjadi Rp 6 juta per bulan. Pinjamannya termasuk utang baik karena meningkatkan penghasilannya. Bayu memakai cicilan 12 bulan untuk beli headset gaming. Headset itu tidak menghasilkan uang dan nilainya turun cepat. Itu utang buruk."}$json$::jsonb where id = 'd1acd9cd-1c8f-4887-bc94-2824ff284491';
update public.content_variants set body = $json${"text":"Rina lost her wallet while returning home and her debit card was blocked. He used a credit card to buy a plane ticket home. As soon as he arrived home, he immediately paid the full bill from his savings. The credit card helps in emergencies because it has a repayment plan."}$json$::jsonb, body_id = $json${"text":"Rina kehilangan dompet saat mudik dan kartu debitnya diblokir. Ia memakai kartu kredit untuk membeli tiket pesawat pulang. Begitu tiba di rumah, ia langsung membayar tagihan penuh dari tabungan. Kartu kredit itu membantu dalam keadaan darurat karena ia punya rencana pelunasan."}$json$::jsonb where id = 'd5833398-ef7b-461b-9137-c8211f138a24';
update public.content_variants set body = $json${"text":"Andi wants to buy crypto. He checked the CoFTRA website and only considered exchanges that were on the list of licensed crypto asset traders. He was not tempted by WhatsApp which offered below market prices."}$json$::jsonb, body_id = $json${"text":"Andi ingin membeli kripto. Ia memeriksa situs Bappebti dan hanya mempertimbangkan bursa yang masuk daftar pedagang aset kripto berizin. Ia tidak tergoda WhatsApp yang menawarkan harga di bawah pasar."}$json$::jsonb where id = 'd5a72ecf-d30a-4d99-b46d-c342bd86ecf2';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"To avoid fines and credit record damage","options":["To avoid fines and credit record damage","Because the bank removes interest if we pay the minimum","Because it makes debts paid off more quickly","Because there is no other way"],"question":"Why pay the minimum on all debts before focusing on one debt?","difficulty":"beginner","explanation":"Minimum payments ensure that there are no delays that damage SLIK and increase costs."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Untuk menghindari denda dan kerusakan rekam kredit","options":["Untuk menghindari denda dan kerusakan rekam kredit","Karena bank menghapus bunga jika kita membayar minimum","Karena itu membuat utang lebih cepat lunas","Karena tidak ada cara lain"],"question":"Mengapa harus membayar minimum pada semua utang sebelum fokus pada satu utang?","difficulty":"beginner","explanation":"Pembayaran minimum menjaga agar tidak ada keterlambatan yang merusak SLIK dan menambah biaya."}$json$::jsonb where id = 'd79d75d8-ea11-468f-966a-9217950a9fe2';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"The name imitates a famous coin so beginners are fooled","options":["The name imitates a famous coin so beginners are fooled","The price is always stable","Guaranteed by LPS","Published by Bank Indonesia"],"question":"Why are fake tokens dangerous?","difficulty":"beginner","explanation":"Fake tokens often use names similar to popular coins to make buyers think they are buying a legitimate asset."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Namanya meniru koin terkenal sehingga pemula tertipu","options":["Namanya meniru koin terkenal sehingga pemula tertipu","Harganya selalu stabil","Dijamin oleh LPS","Diterbitkan oleh Bank Indonesia"],"question":"Kenapa token palsu berbahaya?","difficulty":"beginner","explanation":"Token palsu sering memakai nama mirip koin populer agar pembeli mengira mereka membeli aset yang sah."}$json$::jsonb where id = 'd7b403e9-24ce-428f-b9a1-b5d818f47e4c';

